            border: none;
            padding: 8px 16px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 1rem;
        }
        #reset:hover { background-color: #9f855c; }
        #board {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 6px;
            background-color: #bbada0;
            padding: 6px;
            border-radius: 6px;
            width: 320px;
            height: 320px;
        }
        .cell {
            background-color: #cdc1b4;
            border-radius: 4px;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 1.8rem;
            font-weight: bold;
            color: #776e65;
        }
