        .tile-16 { background-color: #f59563; color: white; }
        .tile-32 { background-color: #f67c5f; color: white; }
        .tile-64 { background-color: #f65e3b; color: white; }
        .tile-128 { background-color: #edcf72; color: white; font-size: 1.6rem; }
        .tile-256 { background-color: #edcc61; color: white; font-size: 1.6rem; }
        .tile-512 { background-color: #edc850; color: white; font-size: 1.6rem; }
        .tile-1024 { background-color: #edc53f; color: white; font-size: 1.4rem; }
        .tile-2048 { background-color: #edc22e; color: white; font-size: 1.4rem; }
    </style>
</head>
<body>
    <div class="game-container">
        <h1>2048</h1>
        <div class="header">
            <div id="score">Score: 0</div>
            <button id="reset">New Game</button>
        </div>
        <div id="board"></div>
    </div>

    <script>
        (function() {
            const SIZE = 4;
            const EMPTY = 0;

            let board = [];
            let score = 0;

            const container = document.getElementById('board');
            const scoreDisplay = document.getElementById('score');
            const resetBtn = document.getElementById('reset');

            // Colors for tiles
            function getTileClass(value) {
                if (value === EMPTY) return '';
                if (value <= 4) return 'tile-' + value;
                return 'tile-' + Math.min(Math.floor(Math.log10(value)), 8) * -1 + 9;
            }

            function createBoard() {
                board = Array(SIZE).fill(null).map(() => Array(SIZE).fill(EMPTY));
                container.innerHTML = '';
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        const cell = document.createElement('div');
                        cell.className = 'cell';
                        cell.dataset.row = r;
                        cell.dataset.col = c;
                        container.appendChild(cell);
                    }
                }
            }

            function spawnTile() {
                let emptyCells = [];
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        if (board[r][c] === EMPTY) {
                            emptyCells.push({ r, c });
                        }
                    }
                }
                if (emptyCells.length > 0) {
                    const index = Math.floor(Math.random() * emptyCells.length);
                    const { r, c } = emptyCells[index];
                    board[r][c] = Math.random() < 0.9 ? 2 : 4;
                }
            }

            function drawBoard() {
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        const cell = container.children[r * SIZE + c];
                        cell.textContent = board[r][c];
                        cell.className = 'cell' + getTileClass(board[r][c]);
                    }
                }
            }

            function getRow(r) {
                return board.map(row => row[r]);
            }

            function setCol(c) {
                const result = [];
                for (let r = 0; r < SIZE; r++) {
                    result.push(board[r][c]);
                }
                return result;
            }

            function processLine(line) {
                // Filter out zeros
                let nonZero = line.filter(val => val !== EMPTY);
                let merged = [];
                let scoreAdd = 0;
                let canMergeNext = false;

                for (let i = 0; i < nonZero.length; i++) {
                    if (canMergeNext) {
                        continue; // Skip this one, it was already merged with previous
                    }

                    if (i + 1 < nonZero.length && nonZero[i] === nonZero[i + 1]) {
                        const newVal = nonZero[i] * 2;
                        merged.push(newVal);
                        scoreAdd += newVal;
                        canMergeNext = true;
                        i++; // Skip next element as it was just merged
                    } else {
                        merged.push(nonZero[i]);
                        canMergeNext = false;
                    }
                }

                while (merged.length < SIZE) {
                    merged.push(EMPTY);
                }
                return { line: merged, scoreAdd };
            }

            function moveLeft() {
                let moved = false;
                for (let r = 0; r < SIZE; r++) {
                    const originalRow = [...getRow(r)];
                    const result = processLine(originalRow);
                    board[r] = result.line;
                    score += result.scoreAdd;
                    if (originalRow.toString() !== result.line.join('')) {
                        moved = true;
                    }
                }
                return moved;
            }

            function moveRight() {
                let moved = false;
                for (let r = 0; r < SIZE; r++) {
                    const originalRow = [...getRow(r)].reverse();
                    const result = processLine(originalRow);
                    board[r] = result.line.reverse();
                    score += result.scoreAdd;
                    if (originalRow.toString() !== result.line.join('')) {
                        moved = true;
                    }
                }
                return moved;
            }

            function moveUp() {
                let moved = false;
                for (let c = 0; c < SIZE; c++) {
                    const originalCol = [...setCol(c)];
                    const result = processLine(originalCol);
                    for (let r = 0; r < SIZE; r++) {
                        board[r][c] = result.line[r];
                    }
                    score += result.scoreAdd;
                    if (originalCol.toString() !== result.line.join('')) {
                        moved = true;
                    }
                }
                return moved;
            }

            function moveDown() {
                let moved = false;
                for (let c = 0; c < SIZE; c++) {
                    const originalCol = [...setCol(c)].reverse();
                    const result = processLine(originalCol);
                    board[c] = result.line.reverse();
                    score += result.scoreAdd;
                    if (originalCol.toString() !== result.line.join('')) {
                        moved = true;
                    }
                }
                return moved;
            }

            function handleMove(direction) {
                let moved;
                switch (direction) {
                    case 'left': moved = moveLeft(); break;
                    case 'right': moved = moveRight(); break;
                    case 'up': moved = moveUp(); break;
                    case 'down': moved = moveDown(); break;
                    default: return false;
                }

                if (moved) {
                    spawnTile();
                    drawBoard();
                    scoreDisplay.textContent = 'Score: ' + score;
                }
                return moved;
            }

            function reset() {
                board = Array(SIZE).fill(null).map(() => Array(SIZE).fill(EMPTY));
                score = 0;

                // Spawn initial tiles
                spawnTile();
                spawnTile();

                drawBoard();
                scoreDisplay.textContent = 'Score: 0';
            }

            function board() {
                return JSON.parse(JSON.stringify(board));
            }

            function setBoard(arr) {
                board = arr;
                drawBoard();
            }

            function score() {
                return score;
            }

            window.game = {
                size: SIZE,
                reset: reset,
                move: handleMove,
                board: board,
                setBoard: setBoard,
                score: score
            };

            document.addEventListener('keydown', function(e) {
                if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) {
                    e.preventDefault();
                    let direction = '';
                    switch(e.key) {
                        case 'ArrowLeft': direction = 'left'; break;
                        case 'ArrowRight': direction = 'right'; break;
                        case 'ArrowUp': direction = 'up'; break;
                        case 'ArrowDown': direction = 'down'; break;
                    }
                    if (handleMove(direction)) {
                        // Already handled in handleMove
                    }
                }
            });

            resetBtn.addEventListener('click', reset);

            // Initialize game
            createBoard();
            reset();
        })();
    </script>
</body>
</html>
